// Photo asset "logo-d" — added by the builder (their own real, local image).
// Use it in any page with:
//   <script src="./assets/logo-d.js"></script>
//   <img data-asset="logo-d" alt="describe the photo">
window.ASSETS = Object.assign(window.ASSETS || {}, { "logo-d": "data:image/png;base64," });
(function () {
  function apply() { document.querySelectorAll('img[data-asset="logo-d"]').forEach(function (img) { img.src = window.ASSETS["logo-d"]; }); }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', apply); else apply();
})();
